mapper.update:
UPDATE t_message
SET read_flag = #{readFlag},
    read_time = now()
WHERE message_id = #{messageId}
  AND receiver_user_type = #{receiverUserType}
  AND receiver_user_id = #{receiverUserId}
  AND read_flag != #{readFlag}

mapper.select:
SELECT * FROM t_message


        AND receiver_user_type = #{query.receiverUserType}


        AND receiver_user_id = #{query.receiverUserId}


        AND message_type = #{query.messageType}



        AND (
        title ILIKE CONCAT('%', #{query.searchWord}, '%')
        OR
        content ILIKE CONCAT('%', #{query.searchWord}, '%')
        )



        -- 2. 注意：这里 read_flag 如果数据库是 boolean，MyBatis 会自动处理
        -- 如果之前因为 smallint 报错，确保数据库字段已改为 boolean
        AND read_flag = #{query.readFlag}



        AND create_time::DATE   >=  #{query.startDate}::DATE


        AND create_time::DATE   <=  #{query.endDate}::DATE



    ORDER BY message_id DESC

SELECT count(1)
FROM t_message
where receiver_user_type = #{receiverUserType}
  AND receiver_user_id = #{receiverUserId}
  AND read_flag = false
